    """
    Matches a grain based on regex
    """
    if not isinstance(tgt, str):
        return False
    if delimiter not in tgt:
        return False
    if opts is None:
        opts = {}
    if "match" not in opts:
        opts["match"] = True
    if "delimiter" not in opts:
        opts["delimiter"] = delimiter
    if "regex" not in opts:
        opts["regex"] = True
    if "ignorecase" not in opts:
        opts["ignorecase"] = True
    if "flags" not in opts:
        opts["flags"] = re.IGNORECASE
    if opts["ignorecase"]:
        opts["flags"] |= re.IGNORECASE
    if opts["regex"]:
        regex = re.compile(opts["match"], opts["flags"])
