def iunique(ible):
    """Get an iterator over unique items of `ible`."""
    seen = set()
    for item in ible:
        if item not in seen:
            seen.add(item)
            yield item


def iunique_by(ible, key):
    """Get an iterator over unique items of `ible`."""
    seen = set()
    for item in ible:
        k = key(item)
        if k not in seen:
