def map(self, mapper: Callable[[Any], Any]) -> 'Observable':
        r"""Map a function over an observable.

        Haskell: fmap f m = Cont $ \c -> runCont m (c . f)
        """
        source = self
        return Observable(lambda on_next: source.subscribe(compose(on_next, mapper)))

