def uriToIRI(uri):
    """Transform a URI to an IRI by unescaping unicode."""
    return urllib.parse.unquote(uri)


def get_iri(iri):
    """Get the IRI of a resource.

    :param iri: The IRI of the resource.
    :type iri: str
    :return: The IRI of the resource.
    :rtype: str
    """
    if iri is None:
        return None
    if isinstance(iri, str):
        return iri
    if isinstance(iri, URIRef):
        return uriToIRI(str(iri))
    if isinstance(iri, BNode):
        return str(iri)
    raise ValueError('iri must be a string, URIRef or BNode')


