def reorient(in_file, newpath=None):
    """Reorient Nifti files to RAS"""
    import os
    import nibabel as nb
    import numpy as np
    from nipype.utils.filemanip import fname_presuffix
    from nipype.interfaces.base import (
        traits,
        TraitedSpec,
        BaseInterfaceInputSpec,
        SimpleInterface,
    )

    class _ReorientInputSpec(BaseInterfaceInputSpec):
        in_file = traits.File(exists=True, mandatory=True, desc="input file")

    class _ReorientOutputSpec(TraitedSpec):
        out_file = traits.File(exists=True, desc="output file")

    class Reorient(SimpleInterface):
        input_spec = _ReorientInputSpec
        output_spec = _ReorientOutputSpec

