def _validate_value(self, value, field_spec, path, errors):
        """Validates that the given field value is valid given the associated
        field spec and path. Any validation failures are added to the given errors
        collection."""
        if value is None:
            return

        if field_spec.type == 'string':
            if not isinstance(value, six.string_types):
                errors.add(path, 'must be a string')
            elif field_spec.pattern and not re.match(field_spec.pattern, value):
                errors.add(path, 'does not match pattern %s' % field_spec.pattern)

        elif field_spec.type == 'integer':
            if not isinstance(value, six.integer_types):
                errors.add(path, 'must be an integer')
            elif field_spec.minimum is not None and value < field_spec.minimum:
                errors.add(path, 'must be greater than or equal to %d' % field_spec.minimum)
            elif field_spec.maximum is not None and value > field_spec.maximum:
                errors.add(path, 'must be less than or equal to %d' % field_spec.maximum)

        elif field_spec.type == 'number':
            if not isinstance(value, (float, int)):
                errors.add(path, 'must be a number')
            elif field_spec.minimum is not None and value < field_spec.minimum:
                errors.add(path, 'must be greater than or equal to %f' % field_spec.minimum)
            elif field_spec.maximum is not None and value > field_spec.maximum:
                errors.add(path, 'must be less than or equal to %f' % field_spec.maximum)

        elif field_spec.type == 'boolean':
            if not isinstance(value, bool):
                errors.add(path, 'must be a boolean')

        elif field_spec.type == 'object':
            if not isinstance(value, dict):
                errors.add(path, 'must be an object')
