mgc_code:
def _merge_fix(d):
    """Fixes keys that start with "&" and "-"
        d = {
          "&steve": 10,
          "-gary": 4
        }
        result = {
          "steve": 10,
          "gary": 4
        }
    """
    for k in d.keys():
        if k[0] == "&":
            d[k[1:]] = d.pop(k)
        elif k[0] == "-":
            d[k[1:]] = -d.pop(k)
    return d

