def readLocalFile(filename, encoding, options):
    """parse an XML file from the filesystem. """
    if encoding is None:
        encoding = 'utf-8'
    try:
        f = open(filename, 'rb')
    except IOError:
        raise IOError("could not open file '%s'" % filename)
    try:
        return read(f, encoding, options)
    finally:
        f.close()


def readURL(url, encoding, options):
    """parse an XML file from the network. """
    if encoding is None:
        encoding = 'utf-8'
    try:
        f = urllib.urlopen(url)
    except IOError:
        raise IOError("could not open URL '%s'" % url)
    try:
        return read(f, encoding, options)
    finally:
        f.close()


