mgc_code:
def download_genome(self, name, genome_dir, localname=None, mask="soft", regex=None, invert_match=False, version=None):
        """
        Download a (gzipped) genome file to a specific directory

        Parameters
        ----------
        name : str
            Genome / species name

        genome_dir : str
            Directory to install genome

        mask: str , optional
            Masking, soft, hard or none (all other strings)
        """
        if not os.path.exists(genome_dir):
            os.makedirs(genome_dir)
        if not localname:
            localname = name
        if not version:
            version = self.get_version(name)
        if not regex:
            regex = self.get_regex(name)
        if not invert_match:
            regex = "^" + regex
        else:
            regex = regex + "$"
        if mask == "soft":
            mask = "softmasked"
        elif mask == "hard":
            mask = "hardmasked"
        else:
            mask = "unmasked"
        url = self.get_url(name, version)
        if not url:
            raise ValueError("No URL found for %s" % name)
        if not self.check_file(genome_dir, localname, version):
            self.download_file(url, genome_dir, localname, version, regex, mask)

hwc_code:
def top_submissions(self):
        """Return a markdown representation of the top submissions."""
        num = min(10, len(self.submissions))
        if num <= 0:
            return ''

        top_submissions = sorted(
            [x for x in self.submissions.values() if self.distinguished or
             x.distinguished is None],
            key=lambda x: (-x.score, -x.num_comments, x.title))[:num]

        if not top_submissions:
            return ''

        retval = self.post_header.format('Top Submissions')
        for sub in top_submissions:
            title = self._safe_title(sub)
            if sub.permalink in sub.url:
                retval += tt('1. {}').format(title)
            else:
                retval += tt('1. [{}]({})').format(title, sub.url)

            retval += ' by {} ({}, [{} comment{}]({}))\n'.format(
                self._user(sub.author), self._points(sub.score),
                sub.num_comments, 's' if sub.num_comments != 1 else '',
                self._permalink(sub))
        return tt('{}\n').format(retval)

