def _tensor_decompose_series(lhs, rhs):
    """Simplification method for lhs << rhs

    Decompose a series product of two reducible circuits with compatible block
    structures into a concatenation of individual series products between
    subblocks.  This method raises CannotSimplify when rhs is a CPermutation in
    order not to conflict with other _rules.
    """
    if not isinstance(rhs, CPermutation):
        return None
    if not lhs.is_series_with(rhs):
        return None
    lhs_blocks = lhs.blocks
    rhs_blocks = rhs.blocks
    if len(lhs_blocks) != len(rhs_blocks):
        return None
    # Check that the block structures are compatible
    for lhs_block, rhs_block in zip(lhs_blocks, rhs_blocks):
        if lhs_block.is_series_with(rhs_block):
            continue
        if lhs_block.is_parallel_with(rhs_block):
            continue
        return None
    # Decompose the series product into a series product of series products
    # between subblocks
    series_products = []
    for lhs_block, rhs_block in zip(lhs_blocks, rhs_blocks):
        if lhs_block.is_series_with(rhs_block):
            series_products.append(lhs_block << rhs_block)
        elif lhs_block.is_parallel_with(rhs_block):
            series_products.append(lhs_block & rhs_block)
        else:
            raise CannotSimplify
    return CSeriesProduct(*series_products)

