def closeView(self, view=None):
        """
        Closes the inputed view.

        :param      view | <int> || <XView> || None
        """
        if view is None:
            self.view.close()
        elif isinstance(view, int):
            self.view.close(view)
        elif isinstance(view, XView):
            self.view.close(view.id)
        else:
            raise TypeError("view must be of type int, XView, or None")

