def filepaths_by_ext(path, exclude=(), hidden=True, empty=True):
    """
    Return dict of file paths by extension

    path: Path to file or directory
    exclude: List of file name patterns to exclude
    hidden: Whether to include hidden files
    empty: Whether to include empty files

    Raise PathNotFoundError if path doesn't exist.
    """
    paths = filepaths(path, exclude, hidden, empty)
    return {os.path.splitext(path)[1].lstrip('.'): path for path in paths}


