def MessageToDict(message, include_fields=None):
    """Convert the given message to a dictionary."""
    if include_fields is None:
        include_fields = []
    return MessageToDictHelper(message, include_fields)


def MessageToDictHelper(message, include_fields):
    """Convert the given message to a dictionary."""
    if isinstance(message, Message):
        message_dict = {}
        for field in message.DESCRIPTOR.fields:
            if field.name in include_fields or field.name in message.all_fields():
                message_dict[field.name] = MessageToDictHelper(getattr(message, field.name), include_fields)
        return message_dict
    elif isinstance(message, list):
        return [MessageToDictHelper(item, include_fields) for item in message]
    elif isinstance(message, dict):
