    """
    return _get_token_store(opts).delete_token(token_id)


def _get_token_store(opts):
    """
    Get the token store.

    :param opts: Salt master config options
    :returns: Token store
    """
    token_store = opts.get("token_store", "file")
    if token_store == "file":
        return FileTokenStore(opts)
    elif token_store == "redis":
        return RedisTokenStore(opts)
    elif token_store == "memcache":
        return MemcacheTokenStore(opts)
    elif token_store == "mysql":
        return MySQLTokenStore(opts)
    elif token_store == "postgres":
        return

