def quote_address(address: str) -> str:
    """
    Quote a subset of the email addresses defined by RFC 821.

    Should be able to handle anything email.utils.parseaddr can handle.
    """
    if not address:
        return ""
    if address[0] == '"':
        return address
    if address.find('@') == -1:
        return address
    if address.find('"') == -1:
        return address
    if address.find('(') == -1:
        return address
    if address.find(')') == -1:
        return address
    if address.find('\\') == -1:
        return address
    if address.find(' ') == -1:
        return address
    return '"' + address + '"'

