def fill_in_table(self, table, worksheet, flags):
        """
        Fills in any rows with missing right hand side data with empty cells.
        """
        max_row = 0
        min_row = sys.maxint
        for row in table:
            if len(row) > max_row:
                max_row = len(row)
            if len(row) < min_row:
                min_row = len(row)
        if max_row != min_row:
            for row in table:
                if len(row) < max_row:
                    row.extend([None]*(max_row-len(row)))

mgc_code:
def fill_in_table(self, table, worksheet, flags):
        """
        Fills in any rows with missing right hand side data with empty cells.
        """
        if table.right_hand_side_is_empty():
            return

        if table.right_hand_side_is_constant():
            self.fill_in_table_with_constant(table, worksheet, flags)
        else:
            self.fill_in_table_with_variable(table, worksheet, flags)

