def CleanAff4Hunts(self):
    """Cleans up old hunt data from aff4."""
    now = rdfvalue.RDFDatetime.Now()
    cutoff = now - rdfvalue.Duration("1d")
    for hunt_urn in self.ListHunts(
        token=self.token,
        start=cutoff,
        limit=1000):
      try:
        hunt = aff4.FACTORY.Open(hunt_urn, mode="rw", token=self.token)
        hunt.Delete()
      except IOError:
        logging.error("Could not delete hunt %s", hunt_urn)

