def recv(dest, compressed=True, mode=None):
    """
    This function receives files copied to the minion using ``salt-cp`` and is
    not intended to be used directly on the CLI.
    """
    if not isinstance(dest, list):
        dest = [dest]
    for chunk in __salt__["cp.recv"]():
        for dest_ in dest:
            recv_chunked(dest_, chunk, compressed=compressed, mode=mode)
    return True


