def CheckDataReceived(self):
        """Tries to extract a Message from the data buffer and process it."""
        if self.data_buffer:
            # If there is data in the buffer, try to extract a message.
            # If the message is valid, process it.
            # If the message is invalid, discard it and try again.
            while self.data_buffer:
                try:
                    message = self.message_parser.Parse(self.data_buffer)
                    self.ProcessMessage(message)
                except MessageParser.MessageParserError:
                    # If the message is invalid, discard it and try again.
                    self.data_buffer = self.data_buffer[1:]

