    """generate a token for a subject"""
    payload = {
        'sub': subject,
        'iat': datetime.utcnow(),
        'exp': datetime.utcnow() + timedelta(days=1)
    }
    token = jwt.encode(payload, self.secret_key, algorithm='HS256')
    return token


