mgc_code:
def submit_curation(self, corpus_id, curations):
        """Submit correct/incorrect curations fo a given corpus.

        Parameters
        ----------
        corpus_id : str
            The ID of the corpus to which the curations apply.
        curations : dict
            A dict of curations with keys corresponding to Statement UUIDs and
            values corresponding to correct/incorrect feedback.
        """
        if not isinstance(curations, dict):
            raise ValueError("curations must be a dict")

        for uuid, curated in curations.items():
            if not isinstance(uuid, str):
                raise ValueError("curations keys must be strings")
            if curated not in ["correct", "incorrect"]:
                raise ValueError(
                    "curations values must be 'correct' or 'incorrect'"
                )

        data = {"corpus_id": corpus_id, "curations": curations}
        return self._post("curation", data=data)

