def set_extern (self, url):
        """
        Match URL against extern and intern link patterns. If no pattern
        matches the URL is extern. Sets self.extern to a tuple (bool,
        bool) with content (is_extern, is_strict).

        @return: None
        """
        self.extern = (False, False)
        if self.intern_patterns:
            for pattern in self.intern_patterns:
                if pattern.match(url):
                    self.extern = (False, True)
                    break
        if self.extern_patterns:
            for pattern in self.extern_patterns:
                if pattern.match(url):
                    self.extern = (True, True)
                    break
        if not self.extern[1]:
            for pattern in self.extern_patterns:
                if pattern.match(url):
                    self.extern = (True, False)
                    break

