def same_dict(d1, d2):
    """! @brief Test whether two dictionaries contain the same values.

    Unlike a simple equality comparison, this function works as expected when the two dictionaries
    are of different types, such as a dict and OrderedDict. The dictionaries must return
    compatible types from indexing.
    """
    if len(d1) != len(d2):
        return False
    for k in d1.keys():
        if k not in d2:
            return False
        if d1[k] != d2[k]:
            return False
    return True


