    """Run select query for each parameter set in separate transaction."""
    if name is None:
        name = query
    with conn.cursor() as cur:
        for parameter_group in parameter_groups:
            cur.execute(query, parameter_group)
            yield {name: [dict(zip(cur.description, row)) for row in cur]}


