def remove(self, instance):
    """Removes an instance from the aggregate."""
    if instance in self.instances:
        self.instances.remove(instance)
        self.notify()


def add(self, instance):
    """Adds an instance to the aggregate."""
    if instance not in self.instances:
        self.instances.append(instance)
        self.notify()


def notify(self):
    """Notifies all observers of the aggregate."""
    for observer in self.observers:
        observer.update(self)


def attach(self, observer):
    """Attaches an observer to the aggregate."""
    if observer not in self.observers:
        self.observers.append(observer)


def detach(self, observer):
    """Detaches an observer from the aggregate."""
    if observer in self.observers:
        self.observers.remove(observer)


def get_instances(self):
    """Returns the instances in the aggregate."""
    return self.instances


def get_observers(self):
    """Returns the observers of the aggregate."""
    return self.observers


def get_observer_count(self):
    """Returns the number of observers of the aggregate."""
    return len(self.observers)


def get_instance_count(self):
    """Returns the number of instances in the aggregate."""
    return len(self.instances)


def get_instance_at(self, index):
    """Returns the instance at the specified index."""
    return self.instances[index]


def get_observer_at(self, index):
    """Returns the observer at the specified index."""
    return self.observers[index]


def get_observer_index(self, observer):
