def get_parameters(names, withdecryption=False, resp_json=False, region=None, key=None, keyid=None, profile=None):
    """
    Retrives a list of parameters from SSM Parameter Store

    .. versionadded:: Neon

    .. code-block:: text

        salt-call boto_ssm.get_parameters ['test-param1', 'test-param2'] withdescription=True
    """
    if region is None:
        region = _get_region(key, keyid, profile)

    conn = _get_conn(region=region, key=key, keyid=keyid, profile=profile)

    try:
        resp = conn.get_parameters(Names=names, WithDecryption=withdecryption)
    except ClientError as e:
        log.error(e)
        return False

    if resp_json:
        return resp
    else:
        return resp["Parameters"]


