        Generates a summary.

        :param title: optional title
        :type title: str
        :param complexity: whether to print the complexity information as well
        :type complexity: bool
        :return: the summary
        :rtype: str
        """
        if title is None:
            title = self.name
        if complexity:
            return "{}:\n{}\n\nComplexity: {}".format(title, self.description, self.complexity)
        else:
            return "{}:\n{}".format(title, self.description)

