def update(gandi, resource, cmdline, kernel, name, size,
           snapshotprofile, delete_snapshotprofile, background):
    """ Update a disk.

    Resource can be a disk name, or ID
    """
    if resource is None:
        raise Exception("No disk specified")

    if cmdline is None:
        raise Exception("No disk specified")

    if kernel is None:
        raise Exception("No kernel specified")

    if name is None:
        raise Exception("No name specified")

    if size is None:
        raise Exception("No size specified")

    if snapshotprofile is None:
        raise Exception("No snapshot profile specified")

    if delete_snapshotprofile is None:
        raise Exception("No delete snapshot profile specified")

    if background is None:
        raise Exception("No background specified")

    disk = gandi.get_disk(resource)

    if disk is None:
        raise Exception("Disk not found")

    if disk.status != "ready":
        raise Exception("Disk not ready")

    if disk.snapshot_profile is not None:
        raise Exception("Disk already has a snapshot profile")

    if disk.kernel is not None:
        raise Exception("Disk already has a kernel")

    if disk.cmdline is not None:
        raise Exception("Disk already has a cmdline")

    if disk.name is not None:
        raise Exception("Disk already has a name")

    if disk.size != size:
        raise Exception("Disk already has a different size")

    if disk.background != background:
        raise Exception("Disk already has a different background")

    disk.cmdline = cmdline
    disk.kernel = kernel
    disk.name = name
    disk.snapshot_profile = snapshotprofile
    disk.delete_snapshot_profile = delete_snapshotprofile
    disk.size = size
    disk.background = background

    disk.update()

    print("Disk updated")

