def _save_all_bookmarks(bookmarks):
    """Save all bookmarks to config."""
    config["bookmarks"] = [bookmark.to_dict() for bookmark in bookmarks]
    config.save()


def _get_bookmark_by_name(name):
    """Get bookmark by name."""
    for bookmark in _load_all_bookmarks():
        if bookmark.name == name:
            return bookmark
    return None


def _get_bookmark_by_url(url):
    """Get bookmark by url."""
    for bookmark in _load_all_bookmarks():
        if bookmark.url == url:
            return bookmark
    return None


def _get_bookmark_by_id(id):
    """Get bookmark by id."""
    for bookmark in _load_all_bookmarks():
        if bookmark.id == id:
            return bookmark
    return None


def _get_bookmark_by_index(index):
    """Get bookmark by index."""
    bookmarks = _load_all_bookmarks()
    if index < len(bookmarks):
        return bookmarks[index]
    return None


def _get_bookmark_by_index_or_name(index_or_name):
    """Get bookmark by index or name."""
    if index_or_name.isdigit():
        return _get_bookmark_by_index(int(index_or_name))
    return _get_bookmark_by_name(index_or_name)


def _get_bookmark_by_index_or_url(index_or_url):
    """Get bookmark by index or url."""
    if index_or_url.isdigit():
        return _get_bookmark_by_index(int(index_or_url))
    return _get_bookmark_by_url(index_or_url)

