        """
        Syncs the scene together with the given datasets to make sure we
        have the proper number of items, by removing non-existant datasets
        and adding new ones.

        :param      scene    | <XChartScene>
                    datasets | <XChartDataset>

        :return     {<XChartDataset>: <XChartDatasetItem>, ..}
        """

        # Get the current items
        items = self.getItems()

        # Get the current datasets
        currentDatasets = self.getDatasets()

        # Get the datasets from the scene
        sceneDatasets = scene.getDatasets()

        # Get the datasets from the datasets
        datasetsDatasets = datasets.getDatasets()

        # Get the datasets from the scene and datasets
        allDatasets = sceneDatasets + datasetsDatasets

        # Remove the datasets that are not in the scene
        for dataset in currentDatasets:
            if dataset not in allDatasets:
                self.removeDataset(dataset)

        # Add the datasets that are not in the scene
        for dataset in allDatasets:
            if dataset not in currentDatasets:
                self.addDataset(dataset)

