def delete_instance(self, instance, using_transactions=True, dry_run=False):
        """
        Calls :meth:`instance.delete` as long as ``dry_run`` is not set.
        """
        if dry_run:
            return
        if using_transactions:
            with transaction.atomic(using=self.using):
                instance.delete()
        else:
            instance.delete()

