def _enable_disable(states, enable):
    """
    Enable or disable a state file from running

    states
        The state function or sls file to enable or disable

    enable
        Enable or disable the state file
    """
    ret = {}
    for state in states:
        if state not in __salt__["state.show_highstate"]():
            ret[state] = {"comment": "State {0} does not exist".format(state)}
            continue
        if enable:
            if state in __salt__["state.show_lowstate"]():
                ret[state] = {"comment": "State {0} is already enabled".format(state)}
                continue
            if __opts__["test"]:
                ret[state] = {"comment": "State {0} is set to be enabled".format(state)}
                continue
            if __salt__["state.enable"](state):
                ret[state] = {"comment": "Enabled state {0}".format(state), "changes": {state: True}}
            else:
