def compute_total(self, precision=None):
        """
        Gets the total of the invoice with a defined decimal precision
        @param precision: int Number of decimal places
        @return: Decimal
        """
        total = Decimal(0)
        for line in self.lines:
            total += line.total(precision)
        return total

