def player_mode_stats(self, player_handle, game_mode=constants.GAME_MODE_WILDCARD, game_region=constants.GAME_REGION_WILDCARD):
        """Returns the stats for a particular mode of play,
        accepts solo, duo and squad.  Will return both regional
        and global stats.  Default gamemode is solo
        by Zac: Add parameter game_region to extract player stats by region directly
        """
        if game_mode == constants.GAME_MODE_SQUAD:
            game_mode = constants.GAME_MODE_SQUAD_FPP
        elif game_mode == constants.GAME_MODE_SOLO:
            game_mode = constants.GAME_MODE_SOLO_FPP
        elif game_mode == constants.GAME_MODE_DUO:
            game_mode = constants.GAME_MODE_DUO_FPP
        elif game_mode == constants.GAME_MODE_WILDCARD:
            game_mode = constants.GAME_MODE_SQUAD_FPP

        if game_region == constants.GAME_REGION_WILDCARD:
            game_region = constants.GAME_REGION_GLOBAL
        elif game_region == constants.GAME_REGION_NA:
            game_region = constants.GAME_REGION_NA
        elif game_region == constants.GAME_REGION_EUROPE:
            game_region = constants.GAME_REGION_EUROPE
        elif game_region == constants.GAME_REGION_ASIA:
            game_region = constants.GAME_REGION_ASIA
        elif game_region == constants.GAME_REGION_AUSTRALIA:
            game_region = constants.GAME_REGION_AUSTRALIA
        elif game_region == constants.GAME_REGION_SOUTH_AMERICA:
            game_region = constants.GAME_REGION_SOUTH_AMERICA
        elif game_region == constants.GAME_REGION_AFRICA:
            game_region = constants.GAME_REGION_AFRICA
        elif game_region == constants.GAME_REGION_MIDDLE_EAST:
            game_region = constants.GAME_REGION_MIDDLE_EAST

        url = constants.PLAYER_MODE_STATS_URL.format(player_handle, game_mode, game_region)

