def _validate_params(self, req):
        """
        Validate parameters of a jsonrpc-request.

        req - request as a jsonrpc-dict

        raises SLOJSONRPCError on validation error
        """
        if req['method'] not in self.methods:
            raise SLOJSONRPCError(
                code=SLOJSONRPCError.METHOD_NOT_FOUND,
                message='Method not found',
                data={'method': req['method']}
            )

        if req['method'] in self.methods_with_params:
            params = req['params']
            if not isinstance(params, dict):
                raise SLOJSONRPCError(
                    code=SLOJSONRPCError.INVALID_PARAMS,
                    message='Invalid params',
                    data={'params': params}
                )

            for param_name, param_type in self.methods_with_params[req['method']].items():
                if param_name not in params:
                    raise SLOJSONRPCError(
                        code=SLOJSONRPCError.INVALID_PARAMS,
                        message='Invalid params',
                        data={'params': params}
                    )

                if not isinstance(params[param_name], param_type):
                    raise SLOJSONRPCError(
                        code=SLOJSONRPCError.INVALID_PARAMS,
                        message='Invalid params',
                        data={'params': params}
