    if not templatetype:
        raise Exception("No templatetype provided")

    return TypeAttr.query.filter_by(templatetype=templatetype).all()

def get_typeattr(templatetype,name):
    """
        Get the typeattr for a given resource type and name
    """
    if not templatetype:
        raise Exception("No templatetype provided")
    if not name:
        raise Exception("No name provided")

    return TypeAttr.query.filter_by(templatetype=templatetype,name=name).first()

