def get_session(self, token_path=None):
        """ Create a requests Session object

        :param Path token_path: (Only oauth) full path to where the token
         should be load from
        :return: A ready to use requests session
        :rtype: OAuth2Session
        """
        if self.auth_type == 'oauth':
            if token_path is None:
                token_path = Path(self.token_path)
            token = self.load_token(token_path)
            if token is None:
                raise ValueError('No token found')
            return OAuth2Session(client_id=self.client_id,
                                 token=token,
                                 auto_refresh_url=self.token_url,
                                 auto_refresh_kwargs=self.token_kwargs,
                                 token_updater=self.save_token)
        elif self.auth_type == 'basic':
            return requests.Session()
        else:
            raise ValueError('Unknown auth type')

