def _get_arguments(func):
    """
    Get the arguments of a function.
    """
    return _namify_arguments(
        dict(inspect.signature(func).parameters)
    )


def _get_default_arguments(func):
    """
    Get the default arguments of a function.
    """
    return _namify_arguments(
        dict(inspect.signature(func).parameters)
    )


def _get_argument_names(func):
    """
    Get the names of the arguments of a function.
    """
    return list(
        _get_arguments(func).keys()
    )


def _get_default_argument_names(func):
    """
    Get the names of the default arguments of a function.
    """
    return list(
        _get_default_arguments(func).keys()
    )


def _get_argument_values(func, **kwargs):
    """
    Get the values of the arguments of a function.
    """
    return {
        key: value
        for key, value in kwargs.items()
        if key in _get_argument_names(func)
    }


def _get_default_argument_values(func, **kwargs):
    """
    Get the values of the default arguments of a function.
    """
    return {
        key: value
        for key, value in kwargs.items()
        if key in _get_default_argument_names(func)
    }


def _get_argument_value(func, name, value):
    """
    Get the value of an argument of a function.
    """
    return _get_argument_values(func, **{name: value})[name]


def _get_default_argument_value(func, name, value):
    """
    Get the value of a default argument of a function.
    """
    return _get_default_argument_values(func, **{name: value})[name]


