def copy_style(shapefile_path):
        """Copy style from the OSM resource directory to the output path.

        .. versionadded: 3.3

        :param shapefile_path: Path to the shapefile that should get the path
            added.
        :type shapefile_path: basestring
        """
        style_path = os.path.join(os.path.dirname(__file__), 'resources', 'style')
        if not os.path.exists(shapefile_path):
            os.makedirs(shapefile_path)
        for file in os.listdir(style_path):
            if file.endswith('.shp'):
                shutil.copy(os.path.join(style_path, file), shapefile_path)

