def emit(signal, *args, **kwargs):
    """
    Emits a signal
    """
    if signal in _callbacks:
        for callback in _callbacks[signal]:
            callback(*args, **kwargs)


def connect(signal, callback):
    """
    Connects a callback to a signal
    """
    if signal not in _callbacks:
        _callbacks[signal] = []
    _callbacks[signal].append(callback)


def disconnect(signal, callback):
    """
    Disconnects a callback from a signal
    """
    if signal in _callbacks:
        _callbacks[signal].remove(callback)


