def parse_operation_type_definition(lexer: Lexer) -> OperationTypeDefinitionNode:
    """OperationTypeDefinition"""
    lexer.advance()
    operation = lexer.token.value
    lexer.advance()
    lexer.expect_token(TokenKind.COLON)
    type = parse_type(lexer)
    return OperationTypeDefinitionNode(
        location=lexer.location,
        operation=operation,
        type=type,
    )


def parse_type_system_definition(lexer: Lexer) -> TypeSystemDefinitionNode:
    """TypeSystemDefinition"""
    if lexer.token.kind == TokenKind.NAME:
        return parse_type_definition(lexer)
    elif lexer.token.kind == TokenKind.BRACE_L:
        return parse_schema_definition(lexer)
    else:
        raise UnexpectedToken(
            f"{lexer.token.kind.name} {lexer.token.value} @ {lexer.location}"
        )


def parse_type_system_extension(lexer: Lexer) -> TypeSystemExtensionNode:
    """TypeSystemExtension"""
    if lexer.token.kind == TokenKind.NAME:
        return parse_type_extension(lexer)
    elif lexer.token.kind == TokenKind.BRACE_L:
        return parse_schema_extension(lexer)

