def get_a_id_lookup(a_file):
    """
    get the id lookup for the sequences in the alignment
    """
    a_id_lookup = {}
    with open(a_file, "r") as a_fh:
        for line in a_fh:
            if line.startswith(">"):
                seq_id = line.strip().split()[0][1:]
                a_id_lookup[seq_id] = seq_id
    return a_id_lookup


