def fix_tree(tree, a_id_lookup, out):
    """
    get the names for sequences in the raxml tree
    """
    for node in tree.findall("node"):
        if node.attrib["id"] in a_id_lookup:
            node.attrib["name"] = a_id_lookup[node.attrib["id"]]
        else:
            node.attrib["name"] = "unknown"
    tree.write(out)

