def BuscarCertConSaldoDisponible(self, cuit_depositante=None,
                        cod_grano=2, campania=1314, coe=None, 
                        fecha_emision_des=None,
                        fecha_emision_has=None,
                 ):
        """Devuelve los certificados de depósito en los que un productor tiene
        saldo disponible para Liquidar/Retirar/Transferir"""
        if cuit_depositante is None:
            raise ValueError('Debe ingresar el CUIT del depositante')
        if coe is None:
            raise ValueError('Debe ingresar el COE del depositante')
        if fecha_emision_des is None:
            raise ValueError('Debe ingresar la fecha de emision del certificado')
        if fecha_emision_has is None:
            raise ValueError('Debe ingresar la fecha de vencimiento del certificado')
        if cod_grano is None:
            raise ValueError('Debe ingresar el codigo del grano')
        if campania is None:
            raise ValueError('Debe ingresar la campania')
        url = self.url + 'BuscarCertConSaldoDisponible'
        params = {
            'cuit_depositante': cuit_depositante,
            'cod_grano': cod_grano,
            'fecha_emision_des': fecha_emision_des,
            'fecha_emision_has': fecha_emision_has,
            'coe': coe,
            'campania': campania,
        }
        response = self.session.get(url, params=params)
        return response.json()

