    if mimetype != 'application/pdf':
        return []
    urls = []
    try:
        pdf = PdfFileReader(BytesIO(bytes))
        for page in range(pdf.getNumPages()):
            page_obj = pdf.getPage(page)
            page_text = page_obj.extractText()
            urls.extend(re.findall(r'http[s]?://(?:[a-zA-Z]|[0-9]|[$-_@.&+]|[!*\(\),]|(?:%[0-9a-fA-F][0-9a-fA-F]))+', page_text))
    except:
        pass
    return urls


def _pdf_find_emails(bytes, mimetype):
    """ This function finds emails inside of PDF bytes. """
    if mimetype != 'application/pdf':
        return []
    emails = []
    try:
        pdf = PdfFileReader(BytesIO(bytes))
        for page in range(pdf.getNumPages()):
            page_obj = pdf.getPage(page)
            page_text = page_obj.extractText()
            emails.extend(re.findall(r'[\w\.-]+@[\w\.-]+', page_text))
    except:
        pass
    return emails


def _pdf_find_phone_numbers(bytes, mimetype):
    """ This function finds phone numbers inside of PDF bytes. """
    if mimetype != 'application/pdf':
        return []
    phone_numbers = []
    try:
        pdf = PdfFileReader(BytesIO(bytes))
        for page in range(pdf.getNumPages()):
            page_obj = pdf.getPage(page)
            page_text = page_obj.extractText()
            phone_numbers.extend(re.findall(r'(\+?\d{1,3}[\s-]?\d{1,3}[\s-]?\d{1,4}[\s-]?\d{1,4}[\s-]?\d{1,9})', page_text))

