def from_filespec(cls, filespec, root=''):
    """Return a list of globs from a filespec dict.

    The format of the dict is {'globs': [ 'list', 'of' , 'strings' ]
                    (optional) 'exclude' : [{'globs' : ... }, ...] }

    The globs are in zglobs format.
    """
    globs = []
    for glob in filespec['globs']:
        globs.append(glob[len(root):])
    if 'exclude' in filespec:
        exclude = []
        for exclude_glob in filespec['exclude']:
            exclude.append(from_filespec(exclude_glob, root=root))
        return cls(globs, exclude=exclude)
    else:
        return cls(globs)


