def validate(schema, data):
    """ Validate the given data against the given schema. """
    validator = jsonschema.Draft4Validator(schema)
    errors = sorted(validator.iter_errors(data), key=str)
    for error in errors:
        print(error.message)
    return not errors


def validate_schema(schema):
    """ Validate the given schema. """
    return validate(SCHEMA, schema)


def validate_data(data):
    """ Validate the given data. """
    return validate(DATA, data)


def validate_schema_and_data(schema, data):
    """ Validate the given schema and data. """
    return validate_schema(schema) and validate_data(data)


def validate_all():
    """ Validate all schemas and data. """
    for name in os.listdir(SCHEMA_DIR):
        if name.endswith('.json'):
            schema = load_validator(name[:-5])
            data = load_validator(name[:-5] + '_data')
            if not validate_schema_and_data(schema, data):
                print('Validation failed for ' + name)
                return False
    return True


def main():
    """ Main entry point. """
    if not validate_all():
        print('Validation failed.')
        sys.exit(1)
    print('Validation succeeded.')


if __name__ == '__main__':
