def recursive_copy_dirs(source_d, destination_d):
    """
    Create dirs and copy all files recursively from source_d, ignoring
    errors (e.g. existing files)
    """
    for root, dirs, files in os.walk(source_d):
        for dir_ in dirs:
            os.mkdir(os.path.join(destination_d, root, dir_))
        for file_ in files:
            try:
                shutil.copy(os.path.join(root, file_),
                            os.path.join(destination_d, root, file_))
            except OSError:
                pass


