def upload_rabbitmq_policy(vhost, policy_name, pattern, definition,
                           apply_to='all', priority=0, restart=True):
    """Upload RabbitMQ policy."""
    rabbitmq_policies_path = '/etc/rabbitmq/policies.json'
    policies = {}
    if os.path.exists(rabbitmq_policies_path):
        with open(rabbitmq_policies_path) as f:
            policies = json.load(f)
    policies.setdefault(vhost, [])
    policies[vhost].append({
        'pattern': pattern,
        'definition': definition,
        'priority': priority,
        'apply-to': apply_to
    })
    with open(rabbitmq_policies_path, 'w') as f:
        json.dump(policies, f)
    if restart:
        service_restart('rabbitmq-server')


