def _set_selinux_context(self):
        """
        Set SELinux context or fields using chcon program. Raises CommandDoesNotExistException
        if the command is not present on the system.

        :return: None
        """
        if self.selinux_context is None:
            return

        if not self.selinux_context_is_set:
            if self.selinux_context_is_file:
                self.selinux_context = self.selinux_context.strip()
                if not os.path.exists(self.selinux_context):
                    raise CommandDoesNotExistException("chcon", "The file '%s' does not exist" % self.selinux_context)
                self.selinux_context = "--reference=%s" % self.selinux_context
            else:
                self.selinux_context = self.selinux_context.strip()

            if self.selinux_context_is_file:
                self.selinux_context = "--reference=%s" % self.selinux_context
            else:
                self.selinux_context = "--type=%s" % self.selinux_context

            self.selinux_context = "chcon %s %s" % (self.selinux_context, self.path)

            self.selinux_context_is_set = True

