def kwargs_limiter(func, **kwargs):
    """ takes a function a keyword arguments and sends only the number of
    keyword arguments the function is expecting
    """
    if len(kwargs) > func.__code__.co_kwonlyargcount:
        raise TypeError(
            "{} takes only {} keyword arguments".format(
                func.__name__, func.__code__.co_kwonlyargcount
            )
        )
    return func(**kwargs)


def args_limiter(func, *args, **kwargs):
    """ takes a function a positional and keyword arguments and sends only the
    number of positional and keyword arguments the function is expecting
    """
    return posargs_limiter(kwargs_limiter(func, **kwargs), *args)


def args_limiter_decorator(func):
    """ decorator that takes a function a positional and keyword arguments and
    sends only the number of positional and keyword arguments the function is
