def to_feature(self, name=None, feature_type='misc_feature'):
        """Create a feature from the current object.

        :param name: Name for the new feature. Must be specified if the DNA
                     instance has no .name attribute.
        :type name: str
        :param feature_type: The type of feature (genbank standard).
        :type feature_type: str

        """
        if name is None:
            if hasattr(self, 'name'):
                name = self.name
            else:
                raise ValueError('Must specify name if DNA instance has no '
                                 'name attribute')

        if feature_type == 'misc_feature':
            feature = SeqFeature(
                FeatureLocation(0, len(self)),
                type=feature_type,
                qualifiers={'label': name}
            )
        elif feature_type == 'CDS':
            feature = SeqFeature(
                FeatureLocation(0, len(self)),
                type=feature_type,
                qualifiers={'label': name, 'translation': self.translate()}
            )
        else:
            raise ValueError('Feature type not recognized')

        return feature

