        raise
    except SystemExit as sys_exit:
        if sys_exit.code == 0:
            report_metric("bus.lizzy-client.success", 1)
        else:
            report_metric("bus.lizzy-client.failed", 1)
        raise
    else:
        report_metric("bus.lizzy-client.success", 1)

