def doi_resolver(bag, doi_resolver_path, doi_resolver_config, doi_resolver_log):
    """
    Run doi_resolver on bag
    :param obj bag: Bag
    :param str doi_resolver_path: Path to doi_resolver
    :param str doi_resolver_config: Path to doi_resolver config
    :param str doi_resolver_log: Path to doi_resolver log
    :return bool: Flag
    """
    if resolved_flag(bag):
        return resolved_flag_set(bag, True)

    # Run doi_resolver
    cmd = [doi_resolver_path, '-c', doi_resolver_config, '-l', doi_resolver_log, bag.path]
    try:
        subprocess.check_call(cmd)
    except subprocess.CalledProcessError:
        return resolved_flag_set(bag, False)

    # Check for doi_resolver log
    if not os.path.exists(doi_resolver_log):
        return resolved_flag_set(bag, False)

    # Check for doi_resolver log
    with open(doi_resolver_log, 'r') as f:
        for line in f:
            if line.startswith('DOI: '):
                return resolved_flag_set(bag, True)

    return resolved_flag_set(bag, False)


