        get_dictkey(In,k,dtype).  If dtype =="", data are strings; if "int", data are integers; if "f", data are floats.
    """
    if dtype == "":
        return [d[k] for d in In]
    elif dtype == "int":
        return [int(d[k]) for d in In]
    elif dtype == "f":
        return [float(d[k]) for d in In]
