def _run_event(self, event):
    """Run an event."""
    if event.type == 'timer':
        self._run_timer(event)
    elif event.type == 'callback':
        self._run_callback(event)
    elif event.type == 'wait':
        self._run_wait(event)
    elif event.type == 'wait_for_all':
        self._run_wait_for_all(event)
    elif event.type == 'wait_for_any':
        self._run_wait_for_any(event)
    elif event.type == 'wait_for_one':
        self._run_wait_for_one(event)
    elif event.type == 'wait_for_none':
        self._run_wait_for_none(event)
    elif event.type == 'wait_for_all_succeeded':
