def is_valid(self):
        """
        Checks the feature list product spec against.
        Checks if all mandartory features are contained;
        Checks that all "never" features are not contained
        :return: boolean
        """
        for feature in self.features:
            if feature.mandatory and feature.name not in self.feature_list:
                return False
            if feature.never and feature.name in self.feature_list:
                return False
        return True

