    """Parse FTP response."""
    code, *text = text.split()
    return int(code), " ".join(text)


def parse_list(text: str) -> List[str]:
    """Parse FTP list."""
    return text.splitlines()


def parse_mlsd(text: str) -> Dict[str, str]:
    """Parse FTP MLSD response."""
    return dict(parse_mlsd_line(line) for line in text.splitlines())


def parse_mlsd_line(line: str) -> Tuple[str, str]:
    """Parse FTP MLSD line."""
    name, *attrs = line.split()
    return name, " ".join(attrs)


def parse_pasv(text: str) -> Tuple[str, int]:
