def _get_stddevs(self, C, stddev_types, num_sites):
        """
        Return total standard deviation.
        """
        if stddev_types is None:
            return None

        if stddev_types == 'all':
            stddevs = [C.stddev(site) for site in range(num_sites)]
        elif stddev_types == 'mean':
            stddevs = [C.stddev(site) for site in range(num_sites)]
        elif stddev_types == 'var':
            stddevs = [C.var(site) for site in range(num_sites)]
        elif stddev_types == 'std':
            stddevs = [C.std(site) for site in range(num_sites)]
        elif stddev_types == 'var_mean':
            stddevs = [C.var(site) / C.mean(site) for site in range(num_sites)]
        elif stddev_types == 'std_mean':
            stddevs = [C.std(site) / C.mean(site) for site in range(num_sites)]
        else:
            raise ValueError('stddev_types must be one of "all", "mean", "var", "std", "var_mean", or "std_mean"')

        return stddevs

