def push(self, statsDict=None, prefix=None, path=None):
    """Push stat values out to Graphite."""
    if not self.enabled:
        return

    if statsDict is None:
        statsDict = self.statsDict

    if prefix is None:
        prefix = self.prefix

    if path is None:
        path = self.path

    for key, value in statsDict.iteritems():
        if isinstance(value, dict):
            self.push(value, prefix, path + [key])
        else:
            self.push_value(prefix, path + [key], value)

    self.statsDict = {}

