def game(year, month, day, team):
    """Return a game for a certain day and team.

    If the team is not a string, it will return a list of games for that team.
    """
    if not isinstance(team, str):
        return [game(year, month, day, t) for t in team]
    else:
        return {
            "year": year,
            "month": month,
            "day": day,
            "team": team,
        }


