def move_entry(self, entry = None, group = None):
        """Move an entry to another group.

        A v1Group group and a v1Entry entry are needed.

        """
        if entry is None:
            raise ValueError("No entry specified")
        if group is None:
            raise ValueError("No group specified")
        if not isinstance(entry, v1Entry):
            raise ValueError("entry is not a v1Entry")
        if not isinstance(group, v1Group):
            raise ValueError("group is not a v1Group")
        if entry.group != self:
            raise ValueError("entry is not in this group")
        if group.vault != self.vault:
            raise ValueError("group is not in this vault")
        if group == entry.group:
            raise ValueError("entry is already in this group")

        # Remove the entry from the old group
        entry.group.entries.remove(entry)
        entry.group = group

        # Add the entry to the new group
        group.entries.append(entry)

