def serialtoflat(self, raw, width=None):
        """Convert serial (byte stream) pixel data to flat row flat pixel."""
        if width is None:
            width = self.width
        if len(raw) != width:
            raise ValueError("Serial data length does not match width")
        return self.serialtoflat_impl(raw, width)

