def collate_fonts_data_by_glyph(fonts_data):
    """Collate individual fonts data into a single glyph data list."""
    glyph_data = {}
    for font_data in fonts_data:
        for glyph_name, glyph_data_dict in font_data.items():
            if glyph_name not in glyph_data:
                glyph_data[glyph_name] = {}
            for key, value in glyph_data_dict.items():
                if key not in glyph_data[glyph_name]:
