mgc_code:
def serialize_on_parent(
            self,
            parent,  # type: ET.Element
            value,  # type: Any
            state  # type: _ProcessorState
    ):
        # type: (...) -> None
        """Serialize the value and adds it to the parent."""
        if value is None:
            return

        if isinstance(value, (list, tuple)):
            for item in value:
                self.serialize_on_parent(parent, item, state)
            return

        if isinstance(value, dict):
            for key, item in value.items():
                self.serialize_on_parent(parent, item, state)
            return

        if isinstance(value, (str, int, float, bool)):
            value = str(value)

        if isinstance(value, ET.Element):
            parent.append(value)
            return

        raise TypeError(
            "Cannot serialize value of type {0}".format(type(value))
        )

