def _get_columns_by_type(sf, col_type):
    """
    Returns a list of names of columns that are of the given type.
    """
    if col_type == 'str':
        return _get_str_columns(sf)
    elif col_type == 'int':
        return _get_int_columns(sf)
    elif col_type == 'float':
        return _get_float_columns(sf)
    elif col_type == 'datetime':
        return _get_datetime_columns(sf)
    elif col_type == 'bool':
