def _thread(self):
        """ Thread entry point: does the job once, stored results, and dies. """
        self.logger.info("Thread %s started", self.name)
        try:
            self.run()
        except Exception as e:
            self.logger.exception("Thread %s failed", self.name)
            self.logger.error("Thread %s failed: %s", self.name, e)
        self.logger.info("Thread %s stopped", self.name)

