def walk(self, node: dict):
        """
        Walk thru schema and dereferencing ``id`` and ``$ref`` instances
        """
        if node.get('id'):
            self.dereference(node)
        if node.get('allOf'):
            for subnode in node['allOf']:
                self.walk(subnode)
        if node.get('oneOf'):
            for subnode in node['oneOf']:
                self.walk(subnode)
