    # we need to create a MultiPoint instance.
    if issubclass(klass, MultiPoint):
        return klass(coordinates)

    # Otherwise, we can just create a Point instance.
    try:
        return klass(*coordinates)
    except GEOSException:
        # If the Point subclass is a subclass of Distance, then
        # we need to create a Distance instance.
        if issubclass(klass, Distance):
            return klass(*coordinates)

        # Otherwise, we can just create a Point instance.
        return klass(*coordinates)

