def _read_nowait(self, n: int) -> bytes:
        """ Read not more than n bytes, or whole buffer is n == -1 """
        chunks = []

        while self._buffer:
            chunk = self._read_nowait_chunk(n)
            chunks.append(chunk)
            if n != -1:
                n -= len(chunk)
                if n == 0:
                    break

        return b''.join(chunks) if chunks else b''

mgc_code:
def _read_nowait(self, n: int) -> bytes:
        """ Read not more than n bytes, or whole buffer is n == -1 """
        if n == -1:
            return self.buffer
        else:
            if n > len(self.buffer):
                n = len(self.buffer)
            data = self.buffer[:n]
            self.buffer = self.buffer[n:]
            return data

