def room_list(request, template="room_list.html"):
    """
    Show a list of all rooms.
    """
    rooms = Room.objects.all()
    return render(request, template, {'rooms': rooms})


def room_create(request, template="room_create.html"):
    """
    Create a new room.
    """
    if request.method == "POST":
        form = RoomForm(request.POST)
        if form.is_valid():
            room = form.save()
            return redirect('room', slug=room.slug)
    else:
        form = RoomForm()
    return render(request, template, {'form': form})


def room_update(request, slug, template="room_update.html"):
    """
    Update a room.
    """
    room = get_object_or_404(Room, slug=slug)
    if request.method == "POST":
        form = RoomForm(request.POST, instance=room)
        if form.is_valid():
            room = form.save()
            return redirect('room', slug=room.slug)
    else:
        form = RoomForm(instance=room)
    return render(request, template, {'form': form})


def room_delete(request, slug, template="room_delete.html"):
    """
    Delete a room.
    """
    room = get_object_or_404(Room, slug=slug)
    if request.method == "POST":
        room.delete()
        return redirect('room_list')
    return render(request, template, {'room': room})


