def grep_match(pattern, text):
    """Take the lines in *text* and return a list of all lines that
    match the pattern.

    """
    return re.findall(pattern, text)


def grep_replace(pattern, replacement, text):
    """Take the lines in *text* and replace all lines that match the
    pattern with the replacement.

    """
    return re.sub(pattern, replacement, text)


def grep_replace_first(pattern, replacement, text):
    """Take the lines in *text* and replace the first line that matches
    the pattern with the replacement.

    """
    return re.sub(pattern, replacement, text,

