def _find_library_paths(lib, path):
    """Find a library path"""
    for p in path:
        f = os.path.join(p, lib)
        if os.path.exists(f):
            yield p


def _find_library_paths_recursive(lib, path):
    """Find a library path"""
    for p in path:
        f = os.path.join(p, lib)
        if os.path.exists(f):
            yield p
        else:
            for p in _find_library_paths_recursive(lib, os.listdir(p)):
                yield p


def _find_library_recursive(lib, path):
    """Find a library"""
    for p in path:
        f = os.path.join(p, lib)
        if os.path.exists(f):
            return f
        else:
            for p in _find_library_paths_recursive(lib, os.listdir(p)):
                f = os.path.join(p, lib)
                if os.path.exists(f):
                    return f
    return None


def _find_library_recursive_with_ext(lib, path, ext):
    """Find a library"""
    for p in path:
        f = os.path.join(p, lib + ext)
        if os.path.exists(f):
            return f
        else:
            for p in _find_library_paths_recursive(lib, os.listdir(p)):
                f = os.path.join(p, lib + ext)
                if os.path.exists(f):
                    return f
    return

