def add_forward_workflow(self, dag, sections, satisfies=None):
        """Add a forward-workflow, return number of nodes added
        """
        if satisfies is None:
            satisfies = []
        nodes = []
        for section in sections:
            if section.name in self.sections:
                raise ValueError("Section %s already exists" % section.name)
            nodes.append(section)
            self.sections[section.name] = section
        dag.add_nodes(nodes)
        for section in sections:
            for prev in section.prev:
                if prev.name not in self.sections:
                    raise ValueError("Section %s does not exist" % prev.name)
                dag.add_edge(self.sections[prev.name], section)
        for section in sections:
            for next in section.next:
                if next.name not in self.sections:
                    raise ValueError("Section %s does not exist" % next.name)
                dag.add_edge(section, self.sections[next.name])
        for section in sections:
            for prev in section.prev:
                if prev.name not in self.sections:
                    raise ValueError("Section %s does not exist" % prev.name)
                if prev.name not in satisfies:
                    raise ValueError("Section %s does not satisfy %s" % (prev.name, section.name))
        return len(nodes)

