    nick_modes = []

    if nick[0] in self.connection.features.prefix:
        nick_modes.append(self.connection.features.prefix[nick[0]])
        nick = nick[1:]

    for mode in nick_modes:
        self.channels[channel].set_mode(mode, nick)

    self.channels[channel].add_user(nick)

