mgc_code:
def _match_serializers_by_accept_headers(self, serializers,
                                             default_media_type):
        """Match serializer by `Accept` headers."""
        if not serializers:
            return None

        if not self.request.accept_mimetypes:
            return serializers[0]

        for media_type, serializer in serializers.items():
            if media_type in self.request.accept_mimetypes:
                return serializer

        return serializers.get(default_media_type)

